--184 ordinary schema cadence: original PIM bodies and every original IAM predicate stay literal.
DO $pre184$BEGIN
 IF current_user<>'postgres' OR session_user<>'postgres' OR current_setting('role',true)<>'none' OR current_setting('session_replication_role')<>'origin' THEN RAISE EXCEPTION '184 owner migration context' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(982376);
 IF NOT EXISTS(SELECT FROM public.migrations m WHERE m.name='182_cold_schema_runtime_admission') OR EXISTS(SELECT FROM public.migrations m WHERE m.name='184_ordinary_schema_admission') OR EXISTS(SELECT FROM pg_proc WHERE pronamespace='public'::regnamespace AND starts_with(proname,'ordinary184_')) THEN RAISE EXCEPTION '184 exact predecessor' USING ERRCODE='55000';END IF;
END$pre184$;
CREATE FUNCTION public.ordinary184_pim_begin() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $ordinary184$
DECLARE owner_id oid:=(SELECT proowner FROM pg_proc WHERE oid='public.pim_dictionary_begin()'::regprocedure);
BEGIN
 IF to_regclass('pg_temp.pim_dictionary_tx_context') IS NULL THEN
  PERFORM public.ordinary182_require_generation();
  CREATE TEMP TABLE pim_dictionary_tx_context(singleton boolean PRIMARY KEY CHECK(singleton),root_xid text NOT NULL,start_at timestamptz NOT NULL,backend_pid integer NOT NULL,duties jsonb NOT NULL,prepared boolean NOT NULL,finalized boolean NOT NULL) ON COMMIT DROP;
  REVOKE ALL ON pg_temp.pim_dictionary_tx_context FROM PUBLIC,dyna_app;
  CREATE CONSTRAINT TRIGGER pim_dictionary_tx_complete AFTER INSERT OR UPDATE ON pg_temp.pim_dictionary_tx_context DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.pim_dictionary_commit_guard();
  SET CONSTRAINTS pim_dictionary_tx_complete DEFERRED;
  INSERT INTO pg_temp.pim_dictionary_tx_context VALUES(true,pg_current_xact_id()::text,transaction_timestamp(),pg_backend_pid(),'[]'::jsonb,false,false);
 END IF;
 IF NOT EXISTS(SELECT FROM pg_class cl WHERE cl.oid=to_regclass('pg_temp.pim_dictionary_tx_context') AND cl.relpersistence='t' AND cl.relowner=owner_id AND NOT EXISTS(SELECT FROM aclexplode(coalesce(cl.relacl,acldefault('r',cl.relowner))) acl WHERE acl.grantee<>owner_id)) OR(SELECT count(*) FROM pg_attribute attr WHERE attr.attrelid=to_regclass('pg_temp.pim_dictionary_tx_context') AND attr.attnum>0 AND NOT attr.attisdropped)<>7 THEN RAISE EXCEPTION 'PIM temporary custody metadata' USING ERRCODE='55000';END IF;
 IF NOT EXISTS(SELECT FROM pg_temp.pim_dictionary_tx_context ctx WHERE ctx.singleton AND ctx.root_xid=pg_current_xact_id()::text AND ctx.start_at=transaction_timestamp() AND ctx.backend_pid=pg_backend_pid()) OR(SELECT count(*) FROM pg_temp.pim_dictionary_tx_context)<>1 THEN RAISE EXCEPTION 'PIM managed root transaction missing' USING ERRCODE='55000';END IF;
END $ordinary184$;
REVOKE ALL ON FUNCTION public.ordinary184_pim_begin() FROM PUBLIC,dyna_app;
GRANT EXECUTE ON FUNCTION public.ordinary184_pim_begin() TO dyna_app;
CREATE FUNCTION public.ordinary184_pim_prepare() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public SET TimeZone='UTC' AS $ordinary184$
DECLARE duty_json jsonb;proof_json jsonb;final_duties jsonb:='[]'::jsonb;
BEGIN
 PERFORM public.ordinary184_pim_begin();PERFORM public.ordinary182_require_generation();
 FOR duty_json IN SELECT duty.value FROM pg_temp.pim_dictionary_tx_context ctx CROSS JOIN LATERAL jsonb_array_elements(ctx.duties) duty(value) ORDER BY duty.value->>'tenant_id',duty.value->>'catalog_id',duty.value->>'user_id',duty.value->>'api_key_id' LOOP
  IF duty_json->'request'<>'null'::jsonb AND public.pim_dictionary_source((duty_json->>'tenant_id')::uuid,(duty_json->>'catalog_id')::uuid,duty_json->'request',true) IS DISTINCT FROM duty_json->'expected_source' THEN RAISE EXCEPTION 'PIM complete source changed before final identity' USING ERRCODE='40001';END IF;
  proof_json:=public.pim_dictionary_identity((duty_json->>'tenant_id')::uuid,(duty_json->>'user_id')::uuid,(duty_json->>'api_key_id')::uuid,duty_json->>'credential_hash',duty_json->>'role',(duty_json->>'writing')::boolean,true);
  final_duties:=final_duties||jsonb_build_array(duty_json||jsonb_build_object('proof',proof_json));
 END LOOP;
 UPDATE pg_temp.pim_dictionary_tx_context SET duties=final_duties,prepared=true,finalized=false;
END $ordinary184$;
REVOKE ALL ON FUNCTION public.ordinary184_pim_prepare() FROM PUBLIC,dyna_app;
GRANT EXECUTE ON FUNCTION public.ordinary184_pim_prepare() TO dyna_app;
CREATE FUNCTION public.ordinary184_approve(release_sha text,native_sha text,profile_sha text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public SET TimeZone='UTC' AS $ordinary184$
BEGIN
 IF current_user<>'postgres' OR session_user<>'postgres' OR current_setting('role',true)<>'none' OR current_setting('session_replication_role')<>'origin' THEN RAISE EXCEPTION '184 controlled owner approval' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(982376);
 IF public.ordinary184_valid() IS DISTINCT FROM true THEN RAISE EXCEPTION '184 managed PIM schema invalid' USING ERRCODE='55000';END IF;
 RETURN public.ordinary182_approve(release_sha,native_sha,profile_sha);
END
$ordinary184$;
REVOKE ALL ON FUNCTION public.ordinary184_approve(text,text,text) FROM PUBLIC,dyna_app;
CREATE FUNCTION public.ordinary184_valid() RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public SET TimeZone='UTC' AS $ordinary184$
BEGIN
 IF (SELECT array_agg(proname::text ORDER BY proname) FROM pg_proc WHERE pronamespace='public'::regnamespace AND starts_with(proname,'ordinary184_')) IS DISTINCT FROM ARRAY['ordinary184_approve','ordinary184_pim_begin','ordinary184_pim_prepare','ordinary184_valid']::text[] THEN RETURN false;END IF;
 IF NOT EXISTS(SELECT FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure('public.ordinary184_pim_begin()') AND encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')='58139c2f299830e53769e859b01bfa14a7e3f970699692510eed4a2e6612faf6' AND pg_get_function_identity_arguments(p.oid)='' AND pg_get_function_result(p.oid)='void' AND l.lanname='plpgsql' AND pg_get_userbyid(p.proowner)='postgres' AND p.prosecdef AND NOT p.proisstrict AND NOT p.proleakproof AND p.proparallel='u' AND p.prokind='f' AND NOT p.proretset AND p.procost=100 AND p.prorows=0 AND p.provolatile='v' AND p.proargmodes IS NULL AND p.pronargdefaults=0 AND p.proargdefaults IS NULL AND p.proargnames IS NOT DISTINCT FROM NULL::text[] AND p.proconfig=ARRAY['search_path=pg_catalog, public']::text[] AND (SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a)='[["postgres","dyna_app","EXECUTE",false],["postgres","postgres","EXECUTE",false]]'::jsonb) THEN RETURN false;END IF;
 IF NOT EXISTS(SELECT FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure('public.ordinary184_pim_prepare()') AND encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')='4c99f0ec5edca0a437b786e9c90dacf49ee700b1e1dd976eb5c871bafeaa0f74' AND pg_get_function_identity_arguments(p.oid)='' AND pg_get_function_result(p.oid)='void' AND l.lanname='plpgsql' AND pg_get_userbyid(p.proowner)='postgres' AND p.prosecdef AND NOT p.proisstrict AND NOT p.proleakproof AND p.proparallel='u' AND p.prokind='f' AND NOT p.proretset AND p.procost=100 AND p.prorows=0 AND p.provolatile='v' AND p.proargmodes IS NULL AND p.pronargdefaults=0 AND p.proargdefaults IS NULL AND p.proargnames IS NOT DISTINCT FROM NULL::text[] AND p.proconfig=ARRAY['search_path=pg_catalog, public','TimeZone=UTC']::text[] AND (SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a)='[["postgres","dyna_app","EXECUTE",false],["postgres","postgres","EXECUTE",false]]'::jsonb) THEN RETURN false;END IF;
 IF NOT EXISTS(SELECT FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure('public.ordinary184_approve(text,text,text)') AND encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')='0f12c613fa79c27b8ce2b3c200f35e828a4e6d509306b44c9a2caa642472ccc0' AND pg_get_function_identity_arguments(p.oid)='release_sha text, native_sha text, profile_sha text' AND pg_get_function_result(p.oid)='jsonb' AND l.lanname='plpgsql' AND pg_get_userbyid(p.proowner)='postgres' AND p.prosecdef AND NOT p.proisstrict AND NOT p.proleakproof AND p.proparallel='u' AND p.prokind='f' AND NOT p.proretset AND p.procost=100 AND p.prorows=0 AND p.provolatile='v' AND p.proargmodes IS NULL AND p.pronargdefaults=0 AND p.proargdefaults IS NULL AND p.proargnames IS NOT DISTINCT FROM ARRAY['release_sha','native_sha','profile_sha']::text[] AND p.proconfig=ARRAY['search_path=pg_catalog, public','TimeZone=UTC']::text[] AND (SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a)='[["postgres","postgres","EXECUTE",false]]'::jsonb) THEN RETURN false;END IF;
 IF NOT EXISTS(SELECT FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure('public.ordinary184_valid()') AND pg_get_function_identity_arguments(p.oid)='' AND pg_get_function_result(p.oid)='boolean' AND l.lanname='plpgsql' AND pg_get_userbyid(p.proowner)='postgres' AND p.prosecdef AND NOT p.proisstrict AND NOT p.proleakproof AND p.proparallel='u' AND p.prokind='f' AND NOT p.proretset AND p.procost=100 AND p.prorows=0 AND p.provolatile='v' AND p.proargmodes IS NULL AND p.pronargdefaults=0 AND p.proargdefaults IS NULL AND p.proargnames IS NOT DISTINCT FROM NULL::text[] AND p.proconfig=ARRAY['search_path=pg_catalog, public','TimeZone=UTC']::text[] AND (SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a)='[["postgres","postgres","EXECUTE",false]]'::jsonb) THEN RETURN false;END IF;
 IF NOT EXISTS(SELECT FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure('public.pim_dictionary_begin()') AND encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')='f2892bc962b03672aa6f23065971eb2fa3448a52426fa57cc3b998ad55782236' AND pg_get_function_identity_arguments(p.oid)='' AND pg_get_function_result(p.oid)='void' AND l.lanname='plpgsql' AND pg_get_userbyid(p.proowner)='postgres' AND p.prosecdef AND NOT p.proisstrict AND NOT p.proleakproof AND p.proparallel='u' AND p.prokind='f' AND NOT p.proretset AND p.procost=100 AND p.prorows=0 AND p.provolatile='v' AND p.proargmodes IS NULL AND p.pronargdefaults=0 AND p.proargdefaults IS NULL AND p.proargnames IS NOT DISTINCT FROM NULL::text[] AND p.proconfig=ARRAY['search_path=pg_catalog, public']::text[] AND (SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a)='[["postgres","dyna_app","EXECUTE",false],["postgres","postgres","EXECUTE",false]]'::jsonb) THEN RETURN false;END IF;
 IF NOT EXISTS(SELECT FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure('public.pim_dictionary_prepare()') AND encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')='848605ca624ebb724d4fc5d057fcd73cfea165ef2a080156a8a93b3715d88e42' AND pg_get_function_identity_arguments(p.oid)='' AND pg_get_function_result(p.oid)='void' AND l.lanname='plpgsql' AND pg_get_userbyid(p.proowner)='postgres' AND p.prosecdef AND NOT p.proisstrict AND NOT p.proleakproof AND p.proparallel='u' AND p.prokind='f' AND NOT p.proretset AND p.procost=100 AND p.prorows=0 AND p.provolatile='v' AND p.proargmodes IS NULL AND p.pronargdefaults=0 AND p.proargdefaults IS NULL AND p.proargnames IS NOT DISTINCT FROM NULL::text[] AND p.proconfig=ARRAY['search_path=pg_catalog, public','TimeZone=UTC']::text[] AND (SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a)='[["postgres","dyna_app","EXECUTE",false],["postgres","postgres","EXECUTE",false]]'::jsonb) THEN RETURN false;END IF;
 RETURN true;
END
$ordinary184$;
REVOKE ALL ON FUNCTION public.ordinary184_valid() FROM PUBLIC,dyna_app;
DO $after184$BEGIN IF public.ordinary184_valid() IS DISTINCT FROM true THEN RAISE EXCEPTION '184 exact installed helpers' USING ERRCODE='55000';END IF;END$after184$;
